// 按 keyOf 去重，保留每个 key 的首个元素，保持输入顺序
// Set 使用 SameValueZero 比较：1 与 "1" 不同，"__proto__" 只是普通键
function uniqueBy(items, keyOf) {
  const seen = new Set();
  const result = [];
  for (const item of items) {
    const key = keyOf(item);
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(item);
  }
  return result;
}

module.exports = { uniqueBy };

const test = require("node:test");
const assert = require("node:assert/strict");
const { uniqueBy } = require("../src/solution.cjs");

test("duplicates keep the first item and input order", () => {
  const items = [
    { id: "a", v: 1 },
    { id: "b", v: 2 },
    { id: "a", v: 3 },
    { id: "c", v: 4 },
    { id: "b", v: 5 },
  ];
  assert.deepEqual(
    uniqueBy(items, (x) => x.id),
    [
      { id: "a", v: 1 },
      { id: "b", v: 2 },
      { id: "c", v: 4 },
    ],
  );
});

test("mixed key types: 1 and '1' are distinct", () => {
  const items = [1, "1", 1, "1", 2, "2"];
  assert.deepEqual(uniqueBy(items, (x) => x), [1, "1", 2, "2"]);
});

test("empty input returns a new empty array", () => {
  const items = [];
  const out = uniqueBy(items, (x) => x);
  assert.deepEqual(out, []);
  assert.notEqual(out, items);
});

test("'__proto__' and similar keys are ordinary keys", () => {
  const items = ["__proto__", "constructor", "__proto__", "toString", "constructor"];
  assert.deepEqual(uniqueBy(items, (x) => x), ["__proto__", "constructor", "toString"]);
});

test("does not mutate input and returns a new array", () => {
  const items = [3, 1, 3, 2, 1];
  const copy = [...items];
  const out = uniqueBy(items, (x) => x);
  assert.deepEqual(items, copy);
  assert.notEqual(out, items);
  assert.deepEqual(out, [3, 1, 2]);
});

