_DIGITS = frozenset("0123456789")


def parse_port(text):
    """将字符串解析为 1..65535 的端口号，非法输入抛出 ValueError。"""
    if not isinstance(text, str):
        raise ValueError("端口必须是字符串")

    # 仅去除 ASCII 空格，制表符/换行等保持非法
    body = text.strip(" ")
    if not body or not _DIGITS.issuperset(body):
        raise ValueError(f"非法端口: {text!r}")

    port = int(body)
    if not 1 <= port <= 65535:
        raise ValueError(f"端口超出范围: {text!r}")
    return port

import os
import sys
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))
from solution import parse_port


class ParsePortTest(unittest.TestCase):
    def test_boundaries(self):
        self.assertEqual(parse_port("1"), 1)
        self.assertEqual(parse_port("65535"), 65535)

    def test_valid_forms(self):
        self.assertEqual(parse_port("  8080  "), 8080)
        self.assertEqual(parse_port("0000080"), 80)
        self.assertEqual(parse_port("00001"), 1)
        self.assertIs(type(parse_port("80")), int)

    def test_out_of_range(self):
        for s in ("0", "000", "65536", "99999", "1" * 5000):
            with self.subTest(s=s), self.assertRaises(ValueError):
                parse_port(s)

    def test_invalid_strings(self):
        bad = [
            "", " ", "   ", "+80", "-80", "-0", "80.0", "80.", ".5",
            "\t80", "80\n", "80\r", " 8 0", "8_0", "0x50", "1e3",
            "٨٠",  # 阿拉伯-印度数字
            "８０",  # 全角数字
            " 80",      # 不换行空格
            "80\x00",
        ]
        for s in bad:
            with self.subTest(s=s), self.assertRaises(ValueError):
                parse_port(s)

    def test_non_string(self):
        for v in (None, 80, 80.0, b"80", bytearray(b"80"), ["80"], True):
            with self.subTest(v=v), self.assertRaises(ValueError):
                parse_port(v)


if __name__ == "__main__":
    unittest.main()

