import copy
import os
import random
import sys
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

from solution import merge_intervals


def brute_force(intervals):
    """逐点覆盖的参照实现（整数闭区间，相邻整数不合并）。"""
    points = sorted({p for s, e in intervals for p in range(s, e + 1)})
    result = []
    for p in points:
        if result and p == result[-1][1] + 1 and _covered_link(intervals, result[-1][1], p):
            result[-1][1] = p
        else:
            result.append([p, p])
    return result


def _covered_link(intervals, a, b):
    # a 与 b 属于同一个输入区间才算连通
    return any(s <= a and b <= e for s, e in intervals)


class MergeIntervalsTest(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(merge_intervals([]), [])

    def test_single(self):
        self.assertEqual(merge_intervals([[2, 5]]), [[2, 5]])

    def test_touching_endpoints_merge(self):
        self.assertEqual(merge_intervals([[1, 3], [3, 5]]), [[1, 5]])

    def test_gap_does_not_merge(self):
        self.assertEqual(merge_intervals([[1, 3], [4, 5]]), [[1, 3], [4, 5]])

    def test_unsorted(self):
        self.assertEqual(
            merge_intervals([[8, 10], [1, 3], [2, 6], [15, 18]]),
            [[1, 6], [8, 10], [15, 18]],
        )

    def test_containment(self):
        self.assertEqual(merge_intervals([[1, 10], [2, 3], [4, 5]]), [[1, 10]])
        self.assertEqual(merge_intervals([[2, 3], [1, 10]]), [[1, 10]])

    def test_duplicates(self):
        self.assertEqual(merge_intervals([[1, 2], [1, 2], [1, 2]]), [[1, 2]])

    def test_point_intervals(self):
        self.assertEqual(merge_intervals([[3, 3], [3, 3], [4, 4]]), [[3, 3], [4, 4]])
        self.assertEqual(merge_intervals([[1, 5], [3, 3]]), [[1, 5]])

    def test_negative_coordinates(self):
        self.assertEqual(
            merge_intervals([[-5, -1], [-1, 2], [-10, -8], [4, 4]]),
            [[-10, -8], [-5, 2], [4, 4]],
        )

    def test_same_start_different_end(self):
        self.assertEqual(merge_intervals([[1, 2], [1, 9], [1, 4]]), [[1, 9]])

    def test_chain(self):
        self.assertEqual(merge_intervals([[5, 6], [1, 2], [3, 4], [2, 3], [4, 5]]), [[1, 6]])

    def test_input_not_mutated(self):
        data = [[8, 10], [1, 3], [2, 6]]
        snapshot = copy.deepcopy(data)
        merge_intervals(data)
        self.assertEqual(data, snapshot)

    def test_output_does_not_alias_input(self):
        data = [[1, 3], [5, 7]]
        result = merge_intervals(data)
        result[0][1] = 99
        self.assertEqual(data, [[1, 3], [5, 7]])

