'use strict';

// ==================== TTLCache ====================
// 惰性过期：不使用定时器，仅在 get 时检查并删除过期条目。

class TTLCache {
  constructor(now) {
    if (typeof now !== 'function') {
      throw new TypeError('now must be a function');
    }
    this._now = now;
    this._entries = new Map();
  }

  set(key, value, ttlMs) {
    // 校验参数：必须是非负有限数字
    if (typeof ttlMs !== 'number' || !Number.isFinite(ttlMs) || ttlMs < 0) {
      throw new RangeError('ttlMs must be a nonnegative finite number');
    }
    this._entries.set(key, { value, expiresAt: this._now() + ttlMs });
  }

  get(key) {
    const entry = this._entries.get(key);
    if (entry === undefined) return undefined;
    // 恰好到达过期时刻即视为过期
    if (this._now() >= entry.expiresAt) {
      this._entries.delete(key);
      return undefined;
    }
    return entry.value;
  }
}

module.exports = { TTLCache };

'use strict';

const test = require('node:test');
const assert = require('node:assert');
const { TTLCache } = require('../src/solution.cjs');

function setup() {
  const clock = { t: 1000 };
  const cache = new TTLCache(() => clock.t);
  return { clock, cache };
}

test('返回未过期的值', () => {
  const { clock, cache } = setup();
  cache.set('a', 1, 100);
  clock.t += 99;
  assert.strictEqual(cache.get('a'), 1);
});

test('恰好到期时返回 undefined 并删除条目', () => {
  const { clock, cache } = setup();
  cache.set('a', 1, 100);
  clock.t += 100;
  assert.strictEqual(cache.get('a'), undefined);
  assert.strictEqual(cache._entries.has('a'), false);
  // 时钟回拨后也不会复活
  clock.t -= 50;
  assert.strictEqual(cache.get('a'), undefined);
});

test('重新 set 会重置过期时间', () => {
  const { clock, cache } = setup();
  cache.set('a', 1, 100);
  clock.t += 60;
  cache.set('a', 2, 100);
  clock.t += 60;
  assert.strictEqual(cache.get('a'), 2);
  clock.t += 40;
  assert.strictEqual(cache.get('a'), undefined);
});

test('重新 set 可以缩短过期时间', () => {
  const { clock, cache } = setup();
  cache.set('a', 1, 100);
  cache.set('a', 2, 10);
  clock.t += 10;
  assert.strictEqual(cache.get('a'), undefined);
});

test('ttl 为 0 时立即过期', () => {
  const { cache } = setup();
  cache.set('a', 1, 0);
  assert.strictEqual(cache.get('a'), undefined);
});

test('支持 false、0、null、undefined 之外的假值', () => {
  const { cache } = setup();
  cache.set('f', false, 100);
  cache.set('z', 0, 100);
  cache.set('n', null, 100);
  cache.set('e', '', 100);
  assert.strictEqual(cache.get('f'), false);
  assert.strictEqual(cache.get('z'), 0);
  assert.strictEqual(cache.get('n'), null);
  assert.strictEqual(cache.get('e'), '');
});

test('未知 key 返回 undefined', () => {
  const { cache } = setup();
  assert.strictEqual(cache.get('nope'), undefined);
});

test('非法 ttlMs 抛出 RangeError 且不写入', () => {
  const { cache } = setup();
  const bad = [-1, NaN, Infinity, -Infinity, '10', null, undefined, {}, 1n];
  for (const ttl of bad) {
    assert.throws(() => cache.set('a', 1, ttl), RangeError, String(ttl));
  }
  assert.strictEqual(cache.get('a'), undefined);
});

test('非法 ttl 不破坏已有条目', () => {
  const { cache } = setup();
  cache.set('a', 1, 100);
  assert.throws(() => cache.set('a', 2, -5), RangeError);
  assert.strictEqual(cache.get('a'), 1);
});

test('不同 key 相互独立', () => {
  const { clock, cache } = setup();
  cache.set('a', 1, 50);
  cache.set('b', 2, 150);
  clock.t += 50;
  assert.strictEqual(cache.get('a'), undefined);
  assert.strictEqual(cache.get('b'), 2);
});

