// ==================== mapLimit：限并发的有序 map ====================

async function mapLimit(items, limit, fn) {
  // 校验参数合法性
  if (!Number.isInteger(limit) || limit < 1) {
    throw new RangeError('limit must be a positive integer');
  }

  const list = Array.from(items);
  const results = new Array(list.length);
  let next = 0;
  let failed = false;

  // 每个 worker 循环领取下一个下标；失败后不再领取新任务
  async function worker() {
    while (!failed && next < list.length) {
      const i = next++;
      try {
        results[i] = await fn(list[i], i);
      } catch (err) {
        failed = true;
        throw err;
      }
    }
  }

  const workers = [];
  for (let k = 0; k < Math.min(limit, list.length); k++) workers.push(worker());
  await Promise.all(workers);
  return results;
}

module.exports = { mapLimit };
EOF
cat > test/solution.test.cjs <<'EOF'
const test = require('node:test');
const assert = require('node:assert/strict');
const { mapLimit } = require('../src/solution.cjs');

function deferred() {
  const d = {};
  d.promise = new Promise((resolve, reject) => {
    d.resolve = resolve;
    d.reject = reject;
  });
  return d;
}

// 让所有已就绪的微任务/回调先跑完
const flush = () => new Promise((r) => setImmediate(r));

test('invalid limit throws RangeError', async () => {
  for (const bad of [0, -1, 1.5, NaN, Infinity, '2', undefined, null]) {
    await assert.rejects(mapLimit([1], bad, async (x) => x), RangeError);
  }
});

test('empty input returns [] without calling fn', async () => {
  let calls = 0;
  assert.deepEqual(await mapLimit([], 3, () => calls++), []);
  assert.equal(calls, 0);
});

test('results keep input order when completion is out of order', async () => {
  const ds = [deferred(), deferred(), deferred()];
  const p = mapLimit([0, 1, 2], 3, (i) => ds[i].promise);
  await flush();
  ds[2].resolve('c');
  ds[0].resolve('a');
  ds[1].resolve('b');
  assert.deepEqual(await p, ['a', 'b', 'c']);
});

test('never exceeds limit and refills slots as calls finish', async () => {
  const ds = Array.from({ length: 5 }, deferred);
  const started = [];
  let active = 0;
  let maxActive = 0;
  const p = mapLimit([0, 1, 2, 3, 4], 2, async (i) => {
    started.push(i);
    maxActive = Math.max(maxActive, ++active);
    try {
      return await ds[i].promise;
    } finally {
      active--;
    }
  });
  await flush();
  assert.deepEqual(started, [0, 1]);
  ds[1].resolve(10);
  await flush();
  assert.deepEqual(started, [0, 1, 2]);
  ds[0].resolve(9);
  ds[2].resolve(11);
  await flush();
  assert.deepEqual(started, [0, 1, 2, 3, 4]);
  ds[3].resolve(12);
  ds[4].resolve(13);
  assert.deepEqual(await p, [9, 10, 11, 12, 13]);
  assert.equal(maxActive, 2);
});

test('limit larger than input works', async () => {
  assert.deepEqual(await mapLimit([1, 2], 10, async (x) => x * 2), [2, 4]);
});

test('passes item and index to fn', async () => {
  const seen = [];
  await mapLimit(['a', 'b'], 1, (x, i) => seen.push([x, i]));
  assert.deepEqual(seen, [['a', 0], ['b', 1]]);
});

test('rejection stops launching new calls; in-flight calls may finish', async () => {
  const ds = Array.from({ length: 5 }, deferred);
  const started = [];
  let inflightFinished = false;
  const p = mapLimit([0, 1, 2, 3, 4], 2, async (i) => {
    started.push(i);
    const v = await ds[i].promise;
    if (i === 0) inflightFinished = true;
    return v;
  });
  const settled = assert.rejects(p, /boom/);
  await flush();
  ds[1].reject(new Error('boom'));
  await settled;
  ds[0].resolve('late'); // 在途调用仍可完成
  await flush();
  assert.equal(inflightFinished, true);
  assert.deepEqual(started, [0, 1]); // 失败后没有再启动 2、3、4
});

test('synchronous throw in fn rejects and stops launching', async () => {
  const started = [];
  await assert.rejects(
    mapLimit([0, 1, 2], 1, (i) => {
      started.push(i);
      throw new Error('sync');
    }),
    /sync/
  );
  assert.deepEqual(started, [0]);
});
