'use strict';

// 默认的真实睡眠实现；测试中应注入假的 sleep
const defaultSleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// ==================== 重试 ====================
async function retry(
  operation,
  { attempts, delayMs = 0, sleep = defaultSleep, shouldRetry = () => true } = {},
) {
  // 校验参数合法性：必须是正整数
  if (!Number.isInteger(attempts) || attempts < 1) {
    throw new RangeError('attempts must be a positive integer');
  }

  for (let attempt = 1; ; attempt++) {
    try {
      return await operation();
    } catch (error) {
      // 次数用尽或不可重试：原样抛出最后一个错误，且不再睡眠
      if (attempt >= attempts || !shouldRetry(error)) throw error;
    }
    await sleep(delayMs);
  }
}

module.exports = { retry };

'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { retry } = require('../src/solution.cjs');

// 构造按脚本依次返回/抛出的操作，并记录调用次数
function scripted(steps) {
  const op = async () => {
    const step = steps[op.calls++];
    if (step.err) throw step.err;
    return step.ok;
  };
  op.calls = 0;
  return op;
}

function fakeSleep() {
  const log = [];
  const sleep = async (ms) => { log.push(ms); };
  sleep.log = log;
  return sleep;
}

test('成功时立即返回，不睡眠', async () => {
  const op = scripted([{ ok: 42 }]);
  const sleep = fakeSleep();
  assert.equal(await retry(op, { attempts: 3, delayMs: 10, sleep }), 42);
  assert.equal(op.calls, 1);
  assert.deepEqual(sleep.log, []);
});

test('失败后重试直到成功，每次重试之间睡眠', async () => {
  const op = scripted([{ err: new Error('a') }, { err: new Error('b') }, { ok: 'done' }]);
  const sleep = fakeSleep();
  assert.equal(await retry(op, { attempts: 5, delayMs: 7, sleep }), 'done');
  assert.equal(op.calls, 3);
  assert.deepEqual(sleep.log, [7, 7]);
});

test('耗尽次数后抛出最后一个错误对象，最后一次失败后不睡眠', async () => {
  const errs = [new Error('1'), new Error('2'), new Error('3')];
  const op = scripted(errs.map((err) => ({ err })));
  const sleep = fakeSleep();
  await assert.rejects(
    retry(op, { attempts: 3, delayMs: 5, sleep }),
    (e) => e === errs[2],
  );
  assert.equal(op.calls, 3);
  assert.deepEqual(sleep.log, [5, 5]);
});

test('shouldRetry 为 false 时立即抛出原错误，不睡眠', async () => {
  const fatal = new Error('fatal');
  const op = scripted([{ err: fatal }, { ok: 1 }]);
  const sleep = fakeSleep();
  await assert.rejects(
    retry(op, { attempts: 3, delayMs: 5, sleep, shouldRetry: () => false }),
    (e) => e === fatal,
  );
  assert.equal(op.calls, 1);
  assert.deepEqual(sleep.log, []);
});

test('shouldRetry 收到错误对象，可按错误区分', async () => {
  const transient = new Error('transient');
  const fatal = new Error('fatal');
  const seen = [];
  const op = scripted([{ err: transient }, { err: fatal }, { ok: 1 }]);
  const sleep = fakeSleep();
  await assert.rejects(
    retry(op, {
      attempts: 5, delayMs: 1, sleep,
      shouldRetry: (e) => { seen.push(e); return e === transient; },
    }),
    (e) => e === fatal,
  );
  assert.deepEqual(seen, [transient, fatal]);
  assert.equal(op.calls, 2);
  assert.deepEqual(sleep.log, [1]);
});

test('attempts 为 1 时不重试', async () => {
  const err = new Error('x');
  const op = scripted([{ err }]);
  const sleep = fakeSleep();
  await assert.rejects(retry(op, { attempts: 1, sleep }), (e) => e === err);
  assert.deepEqual(sleep.log, []);
});

test('同步抛出的操作同样被当作失败处理', async () => {
  let n = 0;
  const op = () => { if (n++ === 0) throw new Error('sync'); return 'ok'; };
  const sleep = fakeSleep();
  assert.equal(await retry(op, { attempts: 2, delayMs: 3, sleep }), 'ok');
  assert.deepEqual(sleep.log, [3]);
});

test('sleep 被 await：睡眠未完成前不会再次调用操作', async () => {
  const events = [];
  let release;
  const sleep = () => new Promise((r) => { release = r; events.push('sleep'); });
  let n = 0;
  const op = async () => { events.push('op'); if (n++ === 0) throw new Error('e'); return 'v'; };
  const p = retry(op, { attempts: 2, delayMs: 1, sleep });
  await new Promise((r) => setImmediate(r));
  assert.deepEqual(events, ['op', 'sleep']);
  release();
  assert.equal(await p, 'v');
  assert.deepEqual(events, ['op', 'sleep', 'op']);
});

test('非法 attempts 抛 RangeError，且不调用操作', async () => {
  for (const attempts of [0, -1, 1.5, NaN, Infinity, '3', null, undefined]) {
    const op = scripted([{ ok: 1 }]);
    await assert.rejects(retry(op, { attempts }), RangeError, String(attempts));
    assert.equal(op.calls, 0);
  }
  await assert.rejects(retry(async () => 1), RangeError);
});

