  const result = await retry(op, { attempts: 5, delayMs: 7, sleep });
  assert.strictEqual(result, 'ok');
  assert.strictEqual(op.count(), 3);
  assert.deepStrictEqual(calls, [7, 7]);
});

test('throws the same last error object after exhaustion, no trailing sleep', async () => {
  const { sleep, calls } = fakeSleep();
  const errs = [new Error('1'), new Error('2'), new Error('3')];
  const op = failingOp(errs, 'never');
  await assert.rejects(
    retry(op, { attempts: 3, delayMs: 5, sleep }),
    (e) => e === errs[2]
  );
  assert.strictEqual(op.count(), 3);
  assert.deepStrictEqual(calls, [5, 5]);
});

