from collections import deque


def topological_order(nodes, edges):
    """返回满足所有 (a, b)（a 在 b 之前）约束的节点顺序；有环（含自环）则抛 ValueError。"""
    # ==================== 建图（边去重，不修改入参） ====================
    succ = {n: set() for n in nodes}
    indeg = dict.fromkeys(succ, 0)
    for a, b in edges:
        if b not in succ[a]:
            succ[a].add(b)
            indeg[b] += 1

    # ==================== Kahn 算法 ====================
    queue = deque(n for n in nodes if indeg[n] == 0)
    order = []
    while queue:
        n = queue.popleft()
        order.append(n)
        for m in succ[n]:
            indeg[m] -= 1
            if indeg[m] == 0:
                queue.append(m)

    # 自环的入度永远不会归零，因此与普通环统一在此检出
    if len(order) != len(succ):
        raise ValueError("graph contains a cycle")
    return order

import copy
import os
import sys
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))
from solution import topological_order  # noqa: E402


def assert_valid(tc, nodes, edges, order):
    tc.assertEqual(sorted(order), sorted(nodes))
    pos = {n: i for i, n in enumerate(order)}
    for a, b in edges:
        tc.assertLess(pos[a], pos[b])


class TopologicalOrderTest(unittest.TestCase):
    def check(self, nodes, edges):
        assert_valid(self, nodes, edges, topological_order(nodes, edges))

    def test_empty(self):
        self.assertEqual(topological_order([], []), [])

    def test_isolated_nodes(self):
        self.check(["a", "b", "c"], [])

    def test_chain(self):
        self.assertEqual(topological_order(["c", "b", "a"], [("a", "b"), ("b", "c")]),
                         ["a", "b", "c"])

    def test_diamond(self):
        self.check(list("abcd"), [("a", "b"), ("a", "c"), ("b", "d"), ("c", "d")])

    def test_mixed_isolated_and_connected(self):
        self.check(list("abcxyz"), [("a", "b"), ("b", "c")])

    def test_duplicate_edges_no_false_cycle(self):
        self.check(["a", "b"], [("a", "b")] * 3)

    def test_self_loop(self):
        with self.assertRaises(ValueError):
            topological_order(["a"], [("a", "a")])

    def test_two_cycle(self):
        with self.assertRaises(ValueError):
            topological_order(["a", "b"], [("a", "b"), ("b", "a")])

    def test_cycle_with_acyclic_part(self):
        with self.assertRaises(ValueError):
            topological_order(list("abcd"), [("a", "b"), ("b", "c"), ("c", "b")])

    def test_inputs_not_mutated(self):
        nodes, edges = ["a", "b", "c"], [("a", "b"), ("a", "b"), ("b", "c")]
        n0, e0 = copy.deepcopy(nodes), copy.deepcopy(edges)
        topological_order(nodes, edges)
        self.assertEqual((nodes, edges), (n0, e0))

    def test_edges_as_generator(self):
        nodes = ["a", "b"]
        self.assertEqual(topological_order(nodes, (e for e in [("a", "b")])), ["a", "b"])

    def test_large_chain_no_recursion_limit(self):
        n = 100_000
        nodes = [str(i) for i in range(n)]
        edges = [(nodes[i], nodes[i + 1]) for i in range(n - 1)]
        self.assertEqual(topological_order(nodes, edges), nodes)


if __name__ == "__main__":
    unittest.main()

from collections import deque


def topological_order(nodes, edges):
    """返回包含所有节点恰好一次的拓扑序；存在环（含自环）时抛出 ValueError。

    Kahn 算法，时间 O(V + E)，空间 O(V + E)。不修改入参。
    """
    # ==================== 建图（边去重） ====================
    succ = {n: set() for n in nodes}
    for a, b in edges:
        succ[a].add(b)

    indegree = dict.fromkeys(succ, 0)
    for targets in succ.values():
        for b in targets:
            indegree[b] += 1

    # ==================== 逐层剥离入度为 0 的节点 ====================
    # 按 nodes 的原始顺序入队，使结果确定
    queue = deque(n for n in nodes if indegree[n] == 0)
    order = []
    while queue:
        n = queue.popleft()
        order.append(n)
        for b in succ[n]:
            indegree[b] -= 1
