from collections import deque


def topological_order(nodes, edges):
    """返回满足所有边约束的节点顺序（Kahn 算法）。

    存在环（含自环）时抛出 ValueError。不修改入参。
    时间 O(V + E)，空间 O(V + E)。
    """
    # ==================== 建图（边去重） ====================
    succ = {n: set() for n in nodes}
    for a, b in edges:
        succ[a].add(b)

    indeg = dict.fromkeys(succ, 0)
    for targets in succ.values():
        for b in targets:
            indeg[b] += 1

    # ==================== 逐层剥离入度为 0 的节点 ====================
    queue = deque(n for n in nodes if indeg[n] == 0)
    order = []
    while queue:
        n = queue.popleft()
        order.append(n)
        for b in succ[n]:
            indeg[b] -= 1
            if indeg[b] == 0:
                queue.append(b)

    # ==================== 未处理完说明有环 ====================
    if len(order) != len(succ):
        raise ValueError("graph contains a cycle")
    return order

