MIN_LIMIT = 1
MAX_LIMIT = 100

# 转义字符选用反斜杠；SQLite 的 LIKE 默认没有转义符，必须配合 ESCAPE 子句
_ESCAPE = "\\"


def _escape_like(text):
    # 先转义转义符本身，再转义通配符，顺序不能颠倒
    return (
        text.replace(_ESCAPE, _ESCAPE * 2)
        .replace("%", _ESCAPE + "%")
        .replace("_", _ESCAPE + "_")
    )


def _clamp_limit(limit):
    # bool 是 int 的子类，必须显式排除
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise ValueError("limit must be an integer")
    return max(MIN_LIMIT, min(MAX_LIMIT, limit))


def search(conn, name_prefix, limit):
    if not isinstance(name_prefix, str):
        raise TypeError("name_prefix must be a str")
    limit = _clamp_limit(limit)
    pattern = _escape_like(name_prefix) + "%"
    return conn.execute(
        "SELECT id, name FROM users "
        "WHERE name LIKE ? ESCAPE '\\' "
        "ORDER BY name, id "
        "LIMIT ?",
        (pattern, limit),
    ).fetchall()
