import csv
import io

_HEADER = ["name", "age"]
_DIGITS = frozenset("0123456789")
_MAX_AGE = 130


def _parse_age(raw):
    # 仅允许 ASCII 数字（str.isdigit / \d 会放行 Unicode 数字）
    if not raw or not _DIGITS.issuperset(raw):
        raise ValueError(f"invalid age: {raw!r}")
    age = int(raw)
    if age > _MAX_AGE:
        raise ValueError(f"age out of range: {raw!r}")
    return age


def read_people(text):
    # newline="" 保留引号内的换行，交给 csv 模块处理
    reader = csv.reader(io.StringIO(text, newline=""), strict=True)
    people = []
    try:
        if next(reader, None) != _HEADER:
            raise ValueError("header must be exactly: name,age")
        for row in reader:
            if len(row) != 2:
                raise ValueError(f"expected 2 columns, got {len(row)}: {row!r}")
            people.append({"name": row[0], "age": _parse_age(row[1])})
    except csv.Error as e:
        raise ValueError(f"invalid CSV: {e}") from e
    return people

