_HEADER = ["name", "age"]
_DIGITS = frozenset("0123456789")
_MAX_AGE = 130


# ==================== 严格 RFC 4180 解析 ====================
# csv 模块会放过 `Bo"b` 这类裸引号，所以这里手写一个严格的小状态机。
def _parse_csv(text):
    rows, row, buf = [], [], []
    in_record = False
    i, n = 0, len(text)
    while i < n:
        c = text[i]
        in_record = True
        if c == '"':
            if buf:
                raise ValueError("quote inside unquoted field")
            i = _read_quoted(text, i + 1, buf)
            if i < n and text[i] not in ',\r\n':
                raise ValueError("garbage after closing quote")
        elif c == ",":
            row.append("".join(buf))
            buf = []
            i += 1
        elif c in "\r\n":
            row.append("".join(buf))
            rows.append(row)
            row, buf, in_record = [], [], False
            i += 2 if text.startswith("\r\n", i) else 1
        else:
            buf.append(c)
            i += 1
    if in_record:
        row.append("".join(buf))
        rows.append(row)
    return rows


def _read_quoted(text, i, buf):
    """从开引号之后读到闭引号之后，返回新下标；`""` 表示一个引号。"""
    n = len(text)
    while i < n:
        if text[i] != '"':
            buf.append(text[i])
            i += 1
        elif text.startswith('""', i):
            buf.append('"')
            i += 2
        else:
            return i + 1
    raise ValueError("unterminated quoted field")


def _parse_age(raw):
    # 仅允许 ASCII 数字（str.isdigit / \d 会放行 Unicode 数字）
    if not raw or not _DIGITS.issuperset(raw):
        raise ValueError(f"invalid age: {raw!r}")
    age = int(raw)
    if age > _MAX_AGE:
        raise ValueError(f"age out of range: {raw!r}")
    return age


def read_people(text):
    rows = _parse_csv(text)
    if not rows or rows[0] != _HEADER:
        raise ValueError("header must be exactly: name,age")
    people = []
    for row in rows[1:]:
        if len(row) != 2:
            raise ValueError(f"expected 2 columns, got {len(row)}: {row!r}")
        people.append({"name": row[0], "age": _parse_age(row[1])})
    return people

