// ==================== 分页收集 ====================
async function collectPages(fetchPage) {
  const items = [];
  const seen = new Set();
  let cursor = null;

  // 仅当 next === null 时结束；空页与空字符串游标均属正常
  while (true) {
    if (cursor !== null) {
      // 同一非空游标被再次请求，视为死循环
      if (seen.has(cursor)) throw new Error(`重复的游标: ${JSON.stringify(cursor)}`);
      seen.add(cursor);
    }
    const page = await fetchPage(cursor);
    for (const item of page.items) items.push(item);
    if (page.next === null) return items;
    cursor = page.next;
  }
}

module.exports = { collectPages };
EOF
