'use strict';

// ==================== 常量与判型 ====================
const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(v) {
  if (v === null || typeof v !== 'object') return false;
  const proto = Object.getPrototypeOf(v);
  return proto === Object.prototype || proto === null;
}

// ==================== 不安全键校验 ====================
// 递归检查对象与数组（含数组内嵌套），发现危险自有键即抛错
function assertSafe(v, path = '$') {
  if (Array.isArray(v)) {
    v.forEach((item, i) => assertSafe(item, `${path}[${i}]`));
  } else if (isPlainObject(v)) {
    for (const key of Object.getOwnPropertyNames(v)) {
      if (UNSAFE_KEYS.has(key)) {
        throw new TypeError(`Unsafe key "${key}" at ${path}`);
      }
      assertSafe(v[key], `${path}.${key}`);
    }
  }
}

// ==================== 深拷贝 ====================
function clone(v) {
  if (Array.isArray(v)) return v.map(clone);
  if (isPlainObject(v)) {
    const out = {};
    for (const key of Object.keys(v)) out[key] = clone(v[key]);
    return out;
  }
  return v;
}

// ==================== 合并 ====================
function merge(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return clone(override);
  const out = clone(base);
  for (const key of Object.keys(override)) {
    out[key] = key in out ? merge(base[key], override[key]) : clone(override[key]);
  }
  return out;
}

function mergeConfig(base, override) {
  assertSafe(base);
  assertSafe(override);
  return merge(base, override);
}

module.exports = { mergeConfig };
