  return proto === Object.prototype || proto === null;
}

// Throws if any own key at any depth (including inside arrays) is unsafe.
function assertSafe(value) {
  if (Array.isArray(value)) {
    for (const item of value) assertSafe(item);
  } else if (value !== null && typeof value === 'object') {
    for (const key of Reflect.ownKeys(value)) {
      if (typeof key === 'string' && UNSAFE_KEYS.has(key)) {
        throw new Error(`Unsafe key rejected: ${key}`);
      }
      assertSafe(value[key]);
    }
  }
}

function deepCopy(value) {
  if (Array.isArray(value)) return value.map(deepCopy);
  if (isPlainObject(value)) {
    const out = {};
    for (const key of Object.keys(value)) out[key] = deepCopy(value[key]);
    return out;
  }
  return value;
}

function merge(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return deepCopy(override);
  const out = {};
  for (const key of Object.keys(base)) {
    if (!Object.prototype.hasOwnProperty.call(override, key)) {
      out[key] = deepCopy(base[key]);
    }
  }
  for (const key of Object.keys(override)) {
    out[key] = Object.prototype.hasOwnProperty.call(base, key)
      ? merge(base[key], override[key])
      : deepCopy(override[key]);
  }
  return out;
}

function mergeConfig(base, override) {
  assertSafe(base);
  assertSafe(override);
  return merge(base, override);
}

module.exports = { mergeConfig };
