'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

// Validates a value and returns a deep copy, rejecting unsafe own keys at any depth.
function cloneChecked(value, ancestors) {
  if (value === null || typeof value !== 'object') {
    if (typeof value === 'function' || typeof value === 'symbol') {
      throw new TypeError('Unsupported value type: ' + typeof value);
    }
    return value;
  }
  if (ancestors.has(value)) throw new TypeError('Circular structure is not supported');
  ancestors.add(value);
  let out;
  if (Array.isArray(value)) {
    out = new Array(value.length);
    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) throw new TypeError('Unsafe key: ' + key);
    }
    for (let i = 0; i < value.length; i++) out[i] = cloneChecked(value[i], ancestors);
  } else if (isPlainObject(value)) {
    out = {};
    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) throw new TypeError('Unsafe key: ' + key);
      out[key] = cloneChecked(value[key], ancestors);
    }
  } else {
    throw new TypeError('Unsupported object type');
  }
  ancestors.delete(value);
  return out;
}

function merge(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return override;
  const out = {};
  for (const key of Object.keys(base)) out[key] = base[key];
  for (const key of Object.keys(override)) {
    out[key] = Object.prototype.hasOwnProperty.call(out, key)
      ? merge(out[key], override[key])
      : override[key];
  }
  return out;
}

/**
 * Merges two JSON-like values. Plain objects merge recursively; arrays and
 * scalars from override replace base. Inputs are never mutated and the result
 * shares no nested objects/arrays with them.
 */
function mergeConfig(base, override) {
  // Validate and deep-copy both inputs first, so unsafe keys are rejected
  // everywhere, even in subtrees that would be overridden.
  const b = cloneChecked(base, new Set());
  const o = cloneChecked(override, new Set());
  return merge(b, o);
}

module.exports = { mergeConfig };
