'use strict';

// ==================== 参数校验 ====================
function isPositiveSafeInt(x) {
  return Number.isSafeInteger(x) && x > 0;
}

function validate(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('total 必须是非负安全整数');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights 必须是非空数组');
  }
  let sum = 0;
  for (let i = 0; i < weights.length; i++) {
    // 用下标访问，稀疏数组的空洞会得到 undefined 并被拒绝
    if (!isPositiveSafeInt(weights[i])) {
      throw new RangeError('weights[' + i + '] 必须是正安全整数');
    }
    sum += weights[i];
    if (!Number.isSafeInteger(sum)) {
      throw new RangeError('weights 之和超出安全整数范围');
    }
    if (!Number.isSafeInteger(total * weights[i])) {
      throw new RangeError('total * weights[' + i + '] 超出安全整数范围');
    }
  }
  return sum;
}

// ==================== 最大余数法 ====================
function splitCents(total, weights) {
  const sum = validate(total, weights);
  const n = weights.length;
  const result = new Array(n);
  const rems = new Array(n);

  // 全程整数运算：quota = total*w/sum，商为底，余数为小数部分（分子）
  let given = 0;
  for (let i = 0; i < n; i++) {
    const num = total * weights[i];
    rems[i] = num % sum;
    result[i] = (num - rems[i]) / sum;
    given += result[i];
  }

  // 余数大者优先，平局按下标靠前者优先
  const order = rems.map((_, i) => i).sort((a, b) => rems[b] - rems[a] || a - b);
  const leftover = total - given; // 恒满足 0 <= leftover < n
  for (let k = 0; k < leftover; k++) {
    result[order[k]] += 1;
  }
  return result;
}

module.exports = { splitCents };

