test('平局：余数相同，下标靠前者得到多余的分', () => {
  assert.deepEqual(splitCents(100, [1, 1, 1]), [34, 33, 33]);
  assert.deepEqual(splitCents(2, [1, 1, 1]), [1, 1, 0]);
  assert.deepEqual(splitCents(1, [5, 5]), [1, 0]);
});

test('平局只发生在余数相等者之间，余数更大者仍优先', () => {
  // quota = 0.5, 0.5, 1 -> 余数 1,1,0 之外无更大者；总额 2：前两者各 0，需分 1 给下标 0
  assert.deepEqual(splitCents(1, [1, 1, 2]), [0, 0, 1]);
  // total=5, w=[1,1,1,2] sum=5 -> 整除
  assert.deepEqual(splitCents(5, [1, 1, 1, 2]), [1, 1, 1, 2]);
});

