'use strict';

// ==================== 参数校验 ====================
function validate(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }
  let sum = 0;
  for (const w of weights) {
    if (!Number.isSafeInteger(w) || w <= 0) {
      throw new RangeError('each weight must be a positive safe integer');
    }
    sum += w;
    if (!Number.isSafeInteger(sum) || !Number.isSafeInteger(total * w)) {
      throw new RangeError('sum or total*weight exceeds safe integer range');
    }
  }
  return sum;
}

// ==================== 最大余数法分配 ====================
function splitCents(total, weights) {
  const sum = validate(total, weights);

  // 用整数取模求余数，避免浮点除法误差；所有余数共享分母 sum
  const rems = [];
  const result = weights.map((w) => {
    const prod = total * w;
    const rem = prod % sum;
    rems.push(rem);
    return (prod - rem) / sum;
  });

  // 剩余分数严格小于 weights.length
  const floorSum = result.reduce((a, b) => a + b, 0);
  const leftover = total - floorSum;

  // 余数降序，平局按下标升序
  const order = weights.map((_, i) => i).sort((a, b) => rems[b] - rems[a] || a - b);
  for (let k = 0; k < leftover; k++) result[order[k]] += 1;

  return result;
}

module.exports = { splitCents };
