// ==================== 参数校验 ====================

function assertSafe(n, label) {
  if (!Number.isSafeInteger(n)) throw new RangeError(`${label} 必须是安全整数`);
}

function validate(total, weights) {
  assertSafe(total, 'total');
  if (total < 0) throw new RangeError('total 不能为负');
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights 必须是非空数组');
  }
  let sum = 0;
  for (const w of weights) {
    assertSafe(w, 'weight');
    if (w <= 0) throw new RangeError('weight 必须为正');
    sum += w;
    assertSafe(sum, 'weights 之和');
    assertSafe(total * w, 'total * weight');
  }
  return sum;
}

// ==================== 最大余数法 ====================

function splitCents(total, weights) {
  const sum = validate(total, weights);

  // 用整数取模求商和余数，避免浮点除法的舍入误差
  const result = new Array(weights.length);
  const rems = new Array(weights.length);
  let allocated = 0;
  for (let i = 0; i < weights.length; i++) {
    const prod = total * weights[i];
    rems[i] = prod % sum;
    result[i] = (prod - rems[i]) / sum;
    allocated += result[i];
  }

  // 余数大者优先，相同则下标小者优先；剩余分数必小于 n
  const order = weights.map((_, i) => i).sort((a, b) => rems[b] - rems[a] || a - b);
  for (let k = 0; k < total - allocated; k++) result[order[k]] += 1;

  return result;
}

module.exports = { splitCents };

