'use strict';

// ==================== 版本号解析 ====================
// 严格三段十进制：每段为 0 或无前导零的数字串，仅 ASCII
const VERSION_RE = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$/;

function parse(v) {
  if (typeof v !== 'string') throw new TypeError('version must be a string');
  const m = VERSION_RE.exec(v);
  if (m === null) throw new TypeError('malformed version: ' + JSON.stringify(v));
  return [m[1], m[2], m[3]];
}

// ==================== 大整数比较 ====================
// 无前导零，故位数多者更大；位数相同则字典序即数值序。不依赖 Number/BigInt
function compareDigits(x, y) {
  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
  if (x === y) return 0;
  return x < y ? -1 : 1;
}

function compareVersion(a, b) {
  const pa = parse(a);
  const pb = parse(b);
  for (let i = 0; i < 3; i++) {
    const c = compareDigits(pa[i], pb[i]);
    if (c !== 0) return c;
  }
  return 0;
}

module.exports = { compareVersion };
