'use strict';

// ==================== Emitter ====================
// event -> Set(listener)；Set 天然去重并保持注册顺序
class Emitter {
  constructor() {
    this.events = new Map();
  }

  on(event, fn) {
    let set = this.events.get(event);
    if (!set) this.events.set(event, (set = new Set()));
    set.add(fn);

    // 退订只生效一次，之后重复调用不会误删重新注册的同一监听器
    let active = true;
    return () => {
      if (!active) return;
      active = false;
      this.off(event, fn);
    };
  }

  off(event, fn) {
    const set = this.events.get(event);
    if (!set) return;
    set.delete(fn);
    if (set.size === 0) this.events.delete(event);
  }

  emit(event, value) {
    const set = this.events.get(event);
    if (!set) return;
    // 快照：emit 期间的增删只影响之后的 emit；异常直接向上抛出
    for (const fn of [...set]) fn(value);
  }
}

module.exports = { Emitter };
EOF
cat > test/emitter.test.js <<'EOF'
'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { Emitter } = require('../src/solution.cjs');

test('calls listeners in registration order, events independent', () => {
  const e = new Emitter();
  const log = [];
  e.on('a', (v) => log.push('a1:' + v));
  e.on('b', (v) => log.push('b:' + v));
  e.on('a', (v) => log.push('a2:' + v));
  e.emit('a', 1);
  assert.deepStrictEqual(log, ['a1:1', 'a2:1']);
});

test('same listener registered once per event', () => {
  const e = new Emitter();
  let n = 0;
  const fn = () => n++;
  e.on('a', fn);
  e.on('a', fn);
  e.emit('a');
  assert.strictEqual(n, 1);
});

test('removal during emit affects only later emits', () => {
  const e = new Emitter();
  const log = [];
  const second = () => log.push('second');
  e.on('a', () => { log.push('first'); e.off('a', second); });
  e.on('a', second);
