class Emitter {
  constructor() {
    // event -> Map(fn -> registration token); Map preserves registration order
    this._events = new Map();
  }

  on(event, fn) {
    let listeners = this._events.get(event);
    if (!listeners) {
      listeners = new Map();
      this._events.set(event, listeners);
    }
    let token = listeners.get(fn);
    if (!token) {
      token = {};
      listeners.set(fn, token);
    }
    // A stale unsubscribe must not remove a later re-registration.
    return () => {
      const current = this._events.get(event);
      if (current && current.get(fn) === token) this._remove(event, fn);
    };
  }

  off(event, fn) {
    this._remove(event, fn);
  }

  emit(event, value) {
    const listeners = this._events.get(event);
    if (!listeners) return;
    for (const fn of Array.from(listeners.keys())) {
      fn(value);
    }
  }

  _remove(event, fn) {
    const listeners = this._events.get(event);
    if (!listeners) return;
    listeners.delete(fn);
    if (listeners.size === 0) this._events.delete(event);
  }
}

module.exports = { Emitter };
EOF
