    if (!set) return;
    set.delete(fn);
    if (set.size === 0) this._events.delete(event);
  }

  emit(event, value) {
    const set = this._events.get(event);
    if (!set) return;
    for (const fn of Array.from(set)) fn(value);
  }
}

