const test = require('node:test');
const assert = require('node:assert');
const { Emitter } = require('../src/solution.cjs');

test('calls listeners in order with value', () => {
  const e = new Emitter(), log = [];
  e.on('a', (v) => log.push(['1', v]));
  e.on('a', (v) => log.push(['2', v]));
  e.emit('a', 5);
  assert.deepStrictEqual(log, [['1', 5], ['2', 5]]);
});

test('listener registered at most once per event', () => {
  const e = new Emitter();
  let n = 0;
  const f = () => n++;
  e.on('a', f);
  e.on('a', f);
  e.emit('a');
  assert.strictEqual(n, 1);
});

test('events are independent', () => {
  const e = new Emitter();
  let a = 0, b = 0;
  const f = () => a++;
  e.on('a', f);
  e.on('b', () => b++);
  e.off('b', f);
  e.emit('a');
  assert.deepStrictEqual([a, b], [1, 0]);
});

test('off for absent listener is harmless', () => {
  const e = new Emitter();
  e.off('x', () => {});
  e.on('x', () => {});
  e.off('x', () => {});
  e.emit('x');
});

test('removal during emit affects only later emits', () => {
  const e = new Emitter(), log = [];
  const b = () => log.push('b');
  e.on('a', () => { log.push('a'); e.off('a', b); });
  e.on('a', b);
  e.emit('a');
  e.emit('a');
  assert.deepStrictEqual(log, ['a', 'b', 'a']);
});

test('addition during emit affects only later emits', () => {
  const e = new Emitter(), log = [];
  const late = () => log.push('late');
  e.on('a', () => { log.push('a'); e.on('a', late); });
  e.emit('a');
  assert.deepStrictEqual(log, ['a']);
  e.emit('a');
  assert.deepStrictEqual(log, ['a', 'a', 'late']);
});

test('double unsubscribe is idempotent', () => {
  const e = new Emitter();
  let n = 0;
  const off = e.on('a', () => n++);
  off();
  off();
  e.emit('a');
  assert.strictEqual(n, 0);
});

test('listener exceptions propagate immediately', () => {
  const e = new Emitter();
  let ran = false;
  e.on('a', () => { throw new Error('boom'); });
  e.on('a', () => { ran = true; });
  assert.throws(() => e.emit('a'), /boom/);
  assert.strictEqual(ran, false);
});
