// ==================== Result 类型 ====================
export type Result<T> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly error: string };

// ==================== 组合子 ====================
// 仅在成功时调用 fn；失败原样返回；fn 抛出的异常直接向上传播
export function mapResult<T, U>(r: Result<T>, fn: (value: T) => U): Result<U> {
  if (!r.ok) return r;
  return { ok: true, value: fn(r.value) };
}

// 成功取值，失败取 fallback
export function unwrapOr<T>(r: Result<T>, fallback: T): T {
  return r.ok ? r.value : fallback;
}

// ==================== 类型检查示例 ====================
const okNum: Result<number> = { ok: true, value: 21 };
const failNum: Result<number> = { ok: false, error: "boom" };

export const exampleDoubled: Result<number> = mapResult(okNum, (n) => n * 2);
export const exampleLabel: Result<string> = mapResult(okNum, (n) => `n=${n}`);
export const exampleFailed: Result<string> = mapResult(failNum, (n) => `n=${n}`);
export const exampleValue: number = unwrapOr(failNum, 0);
EOF
