  const r: Result<number> = { ok: true, value: 2 };
  assert.deepEqual(mapResult(r, (n) => String(n * 3)), { ok: true, value: "6" });
});

test("mapResult does not call fn on failure and returns it unchanged", () => {
  const r: Result<number> = { ok: false, error: "bad" };
