const doubled: Result<number> = mapResult(parsed, (n) => n * 2);
const label: Result<string> = mapResult(doubled, (n) => `n=${n}`);
const text: string = unwrapOr(label, "none");

test("成功时应用 fn", () => {
  assert.deepEqual(doubled, { ok: true, value: 42 });
  assert.equal(text, "n=42");
});

test("失败时不调用 fn，且原样返回同一对象", () => {
  const failure: Result<number> = { ok: false, error: "boom" };
  let calls = 0;
