    calls++;
    return n + 1;
  });
  assert.equal(calls, 0);
  assert.equal(out, failure);
});

test("unwrapOr：成功取值，失败取 fallback", () => {
  assert.equal(unwrapOr({ ok: true, value: 1 }, 0), 1);
  assert.equal(unwrapOr<number>({ ok: false, error: "x" }, 7), 7);
});

test("fn 抛出的异常向上传播", () => {
  assert.throws(
    () =>
      mapResult({ ok: true, value: 1 }, () => {
        throw new Error("fn failed");
