// 返回有序数组中第一个满足 numbers[i] >= target 的下标；若不存在则返回 numbers.length
function lowerBound(numbers, target) {
  // 半开区间 [lo, hi)，hi 取 length 使"全部小于 target"的结果可达
  let lo = 0;
  let hi = numbers.length;
  while (lo < hi) {
    const mid = lo + ((hi - lo) >>> 1);
    if (numbers[mid] < target) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

module.exports = { lowerBound };
EOF
cat > test/solution.test.js <<'EOF'
const test = require('node:test');
const assert = require('node:assert/strict');
const { lowerBound } = require('../src/solution.cjs');

// 参照实现：线性扫描
const naive = (a, t) => {
  const i = a.findIndex((x) => x >= t);
  return i === -1 ? a.length : i;
};

test('空数组返回 0', () => {
  assert.equal(lowerBound([], 5), 0);
});

test('target 大于所有元素时返回 length（原实现缺陷）', () => {
  assert.equal(lowerBound([1, 2, 3], 9), 3);
  assert.equal(lowerBound([5], 6), 1);
});

test('target 小于等于首元素返回 0', () => {
  assert.equal(lowerBound([1, 2, 3], 0), 0);
  assert.equal(lowerBound([1, 2, 3], 1), 0);
});

test('重复元素返回第一个位置', () => {
  assert.equal(lowerBound([1, 2, 2, 2, 3], 2), 1);
  assert.equal(lowerBound([2, 2, 2, 2], 2), 0);
  assert.equal(lowerBound([1, 2, 2, 2, 3], 3), 4);
});

test('target 落在间隙中', () => {
  assert.equal(lowerBound([1, 3, 5], 4), 2);
});

test('不修改输入', () => {
  const a = Object.freeze([1, 2, 2, 5]);
  assert.equal(lowerBound(a, 3), 3);
});

test('与线性扫描对拍', () => {
  for (let n = 0; n <= 8; n++) {
    for (let seed = 0; seed < 50; seed++) {
      const a = Array.from({ length: n }, () => Math.floor(Math.random() * 6)).sort((x, y) => x - y);
      for (let t = -1; t <= 7; t++) assert.equal(lowerBound(a, t), naive(a, t), `${a} t=${t}`);
    }
  }
});
EOF
