import os
import sys
import tempfile
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "src"))
from solution import resolve_upload  # noqa: E402


class ResolveUploadTests(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self._tmp.cleanup)
        base = Path(self._tmp.name).resolve()
        self.root = base / "root"
        self.sibling = base / "root_sibling"  # shares name prefix with root
        self.root.mkdir()
        self.sibling.mkdir()
        (self.sibling / "secret.txt").write_text("x")

    def test_simple_and_nested_nonexistent(self):
        self.assertEqual(resolve_upload(self.root, "a.txt"), self.root / "a.txt")
        self.assertEqual(resolve_upload(self.root, "d/e/f.txt"), self.root / "d/e/f.txt")
        self.assertFalse((self.root / "d").exists())  # nothing created

    def test_inner_dotdot_ok(self):
        self.assertEqual(resolve_upload(self.root, "a/../b.txt"), self.root / "b.txt")

    def test_rejects_absolute(self):
        with self.assertRaises(ValueError):
            resolve_upload(self.root, str(self.root / "a.txt"))

    def test_rejects_root_itself(self):
        for s in ("", ".", "a/..", "./"):
            with self.subTest(s=s), self.assertRaises(ValueError):
                resolve_upload(self.root, s)

    def test_rejects_traversal_and_sibling(self):
        for s in ("../x", "a/../../x", "../root_sibling/secret.txt"):
            with self.subTest(s=s), self.assertRaises(ValueError):
                resolve_upload(self.root, s)

    def test_rejects_symlink_outside(self):
        try:
            os.symlink(self.sibling, self.root / "link", target_is_directory=True)
        except (OSError, NotImplementedError):
            self.skipTest("symlinks unavailable")
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "link/secret.txt")
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "link/new.txt")

    def test_allows_symlink_inside(self):
        (self.root / "real").mkdir()
        try:
            os.symlink(self.root / "real", self.root / "alias", target_is_directory=True)
        except (OSError, NotImplementedError):
            self.skipTest("symlinks unavailable")
        self.assertEqual(resolve_upload(self.root, "alias/f.txt"), self.root / "real" / "f.txt")


if __name__ == "__main__":
    unittest.main()

import os
import sys
import tempfile
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "src"))
from solution import resolve_upload


class ResolveUploadTests(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self._tmp.cleanup)
        base = Path(self._tmp.name).resolve()
        self.root = base / "root"
        self.root.mkdir()
        self.sibling = base / "root_sibling"  # shares root's string prefix
        self.sibling.mkdir()
        (self.sibling / "secret.txt").write_text("x")

    def test_nested_nonexistent(self):
        p = resolve_upload(self.root, "a/b/new.txt")
        self.assertEqual(p, self.root / "a" / "b" / "new.txt")
        self.assertFalse((self.root / "a").exists())  # nothing created

    def test_inner_dotdot_ok(self):
        self.assertEqual(resolve_upload(self.root, "a/../b.txt"), self.root / "b.txt")

    def test_absolute_rejected(self):
        for s in ("/etc/passwd", str(self.root / "f"), "\\evil", "C:\\evil"):
            with self.assertRaises(ValueError):
                resolve_upload(self.root, s)

    def test_root_itself_rejected(self):
        for s in ("", ".", "a/..", "./"):
            with self.assertRaises(ValueError):
                resolve_upload(self.root, s)

    def test_traversal_rejected(self):
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "../other.txt")

    def test_sibling_prefix_rejected(self):
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "../root_sibling/secret.txt")

    @unittest.skipUnless(hasattr(os, "symlink"), "needs symlinks")
    def test_symlink_outside_rejected(self):
        (self.root / "link").symlink_to(self.sibling, target_is_directory=True)
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "link/secret.txt")
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "link/new.txt")

    @unittest.skipUnless(hasattr(os, "symlink"), "needs symlinks")
    def test_symlink_inside_allowed(self):
        (self.root / "real").mkdir()
        (self.root / "alias").symlink_to(self.root / "real", target_is_directory=True)
        self.assertEqual(
            resolve_upload(self.root, "alias/f.txt"), self.root / "real" / "f.txt"
        )


if __name__ == "__main__":
    unittest.main()
